const table=(headers,rows)=>`<div class="preview-table"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((v,i)=>`<td${i===0?' class="record-name"':''}>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
