    crm:`<div class="preview-heading"><div><h2>Your customer workspace</h2><p>Good relationships start with the details.</p></div><span class="preview-label">People</span></div>${table(['Name','Company','Status'],[['<span class="avatar">OC</span>Olivia Chen','Acme Studio',badge('Customer')],['<span class="avatar lilac">PS</span>Priya Sharma','Northstar Labs',badge('Lead','orange')],['<span class="avatar blue">JW</span>James Wilson','Orbit Ventures',badge('Customer')],['<span class="avatar">ET</span>Emma Thompson','Bloom & Co',badge('Lead','orange')]])}<div class="preview-note"><span class="status-dot"></span>Contact details, notes and next steps. All together.</div>`,
