function customerPreview(app) {
 return `<div class="customer-preview"><div class="customer-top"><img src="/logo-ui.png" alt="DryKraft" width="92" height="36"><strong>Acme Studio</strong><span class="preview-account">JD <span>James Diaz</span></span></div><div class="customer-body"><div class="customer-modules" role="tablist" aria-label="Preview modules" aria-orientation="vertical">${modules.map((m,i)=>`<button type="button" role="tab" id="customer-tab-${Object.keys(previewViews)[i]}" aria-controls="customer-panel-${Object.keys(previewViews)[i]}" aria-selected="${i===0}"${i===0?'':' tabindex="-1"'}>${moduleIcon(i)}<span>${['CRM','Sales','Finance','Outreach','Calendar','Automate'][i]}</span></button>`).join('')}</div><div class="customer-crm-panel" role="tabpanel" id="customer-panel-crm" aria-labelledby="customer-tab-crm"><nav class="customer-context" aria-label="CRM preview pages">${[['Overview','/docs/product/customization-dashboards#build-a-dashboard'],['Leads','/docs/product/crm-records#enter-sales-as-soon-as-a-lead-is-created'],['People','/docs/product/crm-records#people-companies-and-leads'],['Companies','/docs/product/crm-records#people-companies-and-leads'],['Tasks','/docs/product/crm-records#tasks-and-activity'],['Activity','/docs/product/crm-records#tasks-and-activity']].map(([n,url])=>`<a href="${url}"${n==='People'?' aria-current="true"':''}>${n}</a>`).join('')}</nav><section class="customer-records" aria-label="Illustrative people"><header><div><h2>People</h2><p>Manage your people and relationships.</p></div><span>Illustrative data</span></header><div class="customer-toolbar"><select aria-label="Preview people status"><option value="all">All people</option><option>Customer</option><option>Lead</option></select><label class="customer-search"><span class="sr-only">Search illustrative people</span><input type="search" placeholder="Search people..." data-preview-search></label><details class="preview-columns"><summary>Columns</summary><label><input type="checkbox" data-preview-company checked> Company</label><label><input type="checkbox" data-preview-owner checked> Owner</label></details><a class="button primary small" href="${escape(app)}/signup">Add person</a></div><div class="customer-table" tabindex="0" role="region" aria-label="Illustrative customer table"><table><thead><tr><th class="customer-choice"><span class="sr-only">Contact to view</span></th><th>Name</th><th data-company>Company</th><th>Status</th><th data-owner>Owner</th></tr></thead><tbody>${previewPeople.map(([id,name,company,status,owner,task],i)=>`<tr data-preview-person="${id}" data-status="${status}"${i===0?' class="selected"':''}><td class="customer-choice"><input type="radio" name="preview-contact" aria-label="Select ${name}" ${i===0?'checked':''}></td><td><button type="button" class="customer-name" aria-label="View ${name}" aria-pressed="${i===0}" data-name="${name}" data-company-value="${company}" data-owner-value="${owner}" data-task="${task}"><span class="customer-photo"><img src="/previews/${id}.png" alt="" width="48" height="48"></span><span><strong>${name}</strong><small>${id}@example.com</small></span></button></td><td data-company>${company}</td><td>${badge(status,status==='Customer'?'green':'blue')}</td><td data-owner><span class="customer-owner">${owner.split(' ').map(n=>n[0]).join('')}</span>${owner}</td></tr>`).join('')}</tbody></table></div><div class="customer-footer"><span data-preview-count role="status">1-4 of 4 people</span><span>Page 1</span></div></section><aside class="customer-detail" aria-label="Illustrative contact details"><header><span class="customer-detail-photo"><img src="/previews/olivia.png" alt="" width="110" height="110" data-detail-photo></span><div><h3 data-detail-name>Olivia Chen</h3><span data-detail-status>Customer</span></div></header><div class="customer-detail-tabs" role="tablist" aria-label="Contact preview"><button role="tab" aria-selected="true" id="detail-tab-details" aria-controls="detail-details" type="button">Details</button><button role="tab" aria-selected="false" tabindex="-1" id="detail-tab-notes" aria-controls="detail-notes" type="button">Notes</button><button role="tab" aria-selected="false" tabindex="-1" id="detail-tab-tasks" aria-controls="detail-tasks" type="button">Tasks</button><button role="tab" aria-selected="false" tabindex="-1" id="detail-tab-activity" aria-controls="detail-activity" type="button">Activity</button></div><div id="detail-details" role="tabpanel" aria-labelledby="detail-tab-details"><dl><div><dt>Email</dt><dd data-detail-email>olivia@example.com</dd></div><div><dt>Company</dt><dd data-detail-company>Acme Studio</dd></div><div><dt>Status</dt><dd data-detail-state>${badge('Customer')}</dd></div><div><dt>Owner</dt><dd data-detail-owner>James Diaz</dd></div></dl><div class="customer-next"><h4>Next action</h4><strong data-detail-task>Review renewal proposal</strong><p>Due Thu, Apr 24, 2025</p></div></div><div id="detail-notes" role="tabpanel" aria-labelledby="detail-tab-notes" hidden><h4>Customer context</h4><p>This illustrative contact is ready for a follow-up. Keep notes with the person so your team can continue the conversation.</p></div><div id="detail-tasks" role="tabpanel" aria-labelledby="detail-tab-tasks" hidden><h4 data-detail-task>Review renewal proposal</h4><p>Assign an owner and a due date for the next step.</p></div><div id="detail-activity" role="tabpanel" aria-labelledby="detail-tab-activity" hidden><h4>Activity history</h4><p>Notes and saved field changes stay with the record. This preview uses fictional data.</p></div><a class="button primary small customer-add-task" href="${escape(app)}/signup">Add a task</a></aside></div>${Object.entries(previewViews).slice(1).map(([key,body],i)=>`<section class="customer-module-panel" role="tabpanel" id="customer-panel-${key}" aria-labelledby="customer-tab-${key}" hidden><span class="preview-example">Illustrative data</span>${body}<a class="text-link" href="${modules[i+1].path}">Explore ${modules[i+1].name.toLowerCase()} ${arrow}</a></section>`).join('')}</div></div>`;
}
function home(app) {return `<section class="hero product-first"><div class="hero-copy"><h1>Your customers. Your pipeline.<br>One workspace.</h1><p>Connect CRM, sales, finance and outreach. Shape the fields, dashboards<br class="hero-line"> and workflows around your team.</p><div class="hero-actions"><a class="button primary" href="${escape(app)}/signup">Start your 15-day free trial</a><a class="button secondary" href="/product">Explore the product</a></div><div class="hero-footnote">No card required to try.</div></div>${customerPreview(app)}</section>${renderLaunchFilm()}${journey()}<section class="section"><div class="section-intro"><h2>From the first conversation<br>to the work that follows.</h2><p>Five connected modules. One customer story, with a clear place for each next step.</p></div>${moduleLinks()}</section><section class="customize section"><div><h2>Track the numbers<br>your team works with.</h2><p>Define your own objects and fields, choose the columns in your tables, and build dashboard widgets with counts, sums, averages, filters and date ranges. Edit a widget later or download its dashboard report. Pick a report currency so financial totals stay meaningful.</p><a class="text-link" href="/product/customization">Explore customization ${arrow}</a></div><div class="field-sheet"><div class="field-sheet-heading"><strong>Make a KPI your own</strong><span>Dashboard</span></div><dl><div><dt>Widget title</dt><dd>Our open pipeline</dd></div><div><dt>Calculation</dt><dd>Sum of deal value</dd></div><div><dt>Report currency</dt><dd>INR - Indian Rupee</dd></div><div><dt>Display</dt><dd>Bar chart, grouped by stage</dd></div></dl><p>Follow what matters to your team.</p></div></section>${channelLinks()}${renderProductTour()}${resourceLinks()}${faq()}`;}

