const guideLinks=[['/guides/crm-setup','Set up your customer workspace','Start with people, companies and leads. Add the fields your team uses and import existing records with a preview.'],['/guides/invoices-and-expenses','Follow the invoice and expense workflow','Set issuer details, review a draft, issue its PDF and record payments. Give expenses an approval trail.'],['/guides/multi-currency','Make multi-currency totals useful','Choose default and enabled currencies, preserve the original amounts and select the right currency for each report.'],['/guides/outreach-setup','Review your first campaign or sequence','Connect email, SMS, QCall or WhatsApp, choose a consenting audience and understand what launch will do.'],['/guides/first-workflow','Build and inspect your first workflow','Create a task from a manual trigger, publish the draft and follow the saved execution before adding business events.'],['/guides/team-and-security','Bring teammates in with the right access','Choose workspace roles, share invitation links and review the sessions attached to your own account.'],['/guides/trial-and-billing','Plan your trial and workspace seats','Understand the 15-day trial, review seat counts and manage billing settings.']];
function resourceLinks() {return `<section class="resource-section section"><div class="section-intro"><h2>A practical place<br>to start.</h2><p>Walk through the work you can do in DryKraft, with clear steps and examples.</p></div><div class="resource-links">${guideLinks.map(([url,title,text])=>`<a href="${url}"><div><h3>${title}</h3><p>${text}</p></div>${arrow}</a>`).join('')}</div></section>`;}
const productDetails={
  calendar:{intro:'Let guests choose a time your team can actually host. Keep appointments, availability and their next action with the rest of your workspace.',steps:[['A month you can work from','Start in Month view, select a date for its agenda or switch to a chronological list. Open appointments to see the guest, location and change history.'],['Availability for real working days','Set personal, team or service calendars with working hours, holiday overrides, notice and buffers. Assign the next available host with round robin or require every host to be free.'],['A booking link for your guests','Publish availability deliberately. Guests choose their timezone and available time, then receive a private management link and calendar download.']],follow:'Turn appointment changes into the next useful action.',next:'/product/automation'},
  crm:{intro:'Go from a name in a spreadsheet to a relationship your team can pick up and continue.',steps:[['People and companies','Keep contact details and company information together. Add notes and follow-up tasks where the conversation happens.'],['Leads with context','Track sources, statuses and potential value. Convert a qualified lead into a contact record, then create a deal for the opportunity.'],['Fields that fit','Add the details your process depends on. Custom objects and fields keep your workspace useful as your business changes.']],follow:'Move a qualified lead into your sales pipeline.',next:'/product/sales'},
  sales:{intro:'See where opportunities stand, who owns the conversation and what needs to happen next.',steps:[['A pipeline for your process','Create pipelines and arrange stages around the way your team sells. Move deals between stages or choose a stage directly.'],['Every opportunity has context','Connect a deal to its contact, record the value and currency, set a close date and track the owner and status. Read saved stage changes in the deal’s history.'],['A view of the numbers','Follow deal values in the dashboard. Different currencies remain separate, so your pipeline totals keep their meaning.']],follow:'Turn a won deal into an invoice draft.',next:'/product/finance'},
  finance:{intro:'Customer details, invoice lines and approval decisions, connected to the work that created them.',steps:[['Invoices from draft to paid','Add line items, discounts and taxes. Review and issue a uniquely numbered invoice, then download its PDF and record received payments.'],['Expenses with a clear trail','Capture the vendor, amount, currency, included tax and receipt reference. Submit an expense for approval before recording payment.'],['Currencies managed your way','Choose the currencies your company works in. KWD supports three decimal places; existing records keep their denomination when defaults change.']],follow:'Connect finance events to the next action.',next:'/product/automation'},
  automation:{intro:'Map the steps once, then let record changes, webhooks or schedules start the work.',steps:[['Build the path visually','Connect triggers, conditions, ordered Switch paths and actions in one canvas. Filter, map, sort, limit, deduplicate or aggregate JSON lists before the next step. Search for steps, copy connected actions, organize groups and undo draft edits. Search current CRM records by text or smart list, then use Loop to run actions for each item in that page. Each item has separate saved results, waits and recovery; the Completed path runs once. Prepare dates with timezone-aware display, calendar shifts and elapsed differences. Create tasks, add internal notes, add or remove contact tags, move deals between pipeline stages, link records through relationship fields, assign current teammates, update CRM records or generate finance drafts. Publish reusable workflows with typed inputs and returned values, then call a pinned version from another workflow. Publish a dedicated Error trigger workflow and select its exact version on a source trigger. After retries are exhausted it runs once with failure metadata; execution details link the two runs. Paused handlers are skipped, and handlers cannot recursively launch more automatic handlers. Parents wait while their children run, and saved bindings keep retries from creating another child. Request a GraphQL API with a literal document, typed context variables and a saved credential; inspect its data and choose whether partial results can continue. Parse CSV text into records or create CSV with ordered columns in the same workflow; quoted multiline values are supported, and text formulas are escaped for spreadsheet use. Parse XML into an ordered document tree or create XML while preserving namespaces and mixed text. Transform JSON with a JavaScript or Python Code step in an isolated runtime, with an explicit input, return value and time limit. Split work into named paths, retain their progress across waits and retries, and merge collected outputs or item lists before continuing once.'],['Review before you publish','Keep a workflow as a draft while you check its behavior. Publishing preserves a version for its executions.'],['Know what happened','Inspect saved inputs, step results and recovery history. Review a failed-step replay to keep completed outputs, or deliberately rerun the original version. A full rerun can repeat actions.']],follow:'Shape a connected workspace for your team.',next:'/product'},
  outreach:{intro:'Bring your CRM audience into email, SMS, AI voice and WhatsApp. Review consent and each connection before launching a campaign or sequence.',steps:[['Choose the audience','Use a CRM object or smart list. Review eligible contacts with Marketing consent, a valid channel address and no matching suppression.'],['Give follow-ups a path','A campaign sends one step. A sequence supports up to 20 steps in one channel, with waits, personalisation and reply-aware stopping where supported.'],['Keep results honest','Pause, resume or cancel future work and inspect execution history. Provider acceptance and confirmed delivery are different states.']],follow:'Choose the channel that fits your conversation.',next:'/docs/product/outreach'},
};
const moduleContent={
  calendar:[['Give the conversation a place in your week','Create a calendar around the work being scheduled: a personal follow-up, a team consultation or a service appointment. Choose current workspace hosts, the duration and a named timezone. Working hours and date overrides keep availability tied to the days your team can actually work. Add advance notice and buffers so appointments leave room for preparation.','The Month view gives the team a familiar way to scan appointments; Agenda keeps upcoming conversations in order. Open a booking to edit internal notes, change its time, cancel it or record attendance after it starts. Linked CRM records gain meeting activity, and the appointment’s version history preserves each change.'],['Share availability with clear boundaries','Public booking starts disabled. Enable the calendar link when its description, location and working hours are ready to share. Guests see available times and choose a timezone without seeing host names or other guests. Confirmation includes a private link to manage that booking and an ICS download. DryKraft does not automatically send a confirmation email.','Native Google and Outlook connections import busy event times to prevent overlaps. Optional exports write DryKraft appointment titles, times and locations to the selected provider calendar without guest lists or internal notes. Stale availability blocks bookings for that host until sync recovers. Provider edits require review before the DryKraft values overwrite them; account approval and live permissions are separate setup steps.'],['Keep follow-up connected','Appointment creation, rescheduling, cancellation, attendance and reminder-due events can start a shared workflow. A reminder can create a task or continue into a configured provider action. The Book appointment action uses the same working hours and conflict checks as a booking made in the app.','Reminder events are checked about once per minute; they are not automatic message delivery. Calendars currently support up to 20 hosts, 100 definitions per workspace and a 90-day public horizon. Calendar sync verifies a bounded provider range and freezes uncertain writes instead of blindly creating duplicate events. Read the setup guide for those limits and the difference between a configured connection and verified live provider acceptance.']],
  outreach:[["One audience, four ways to reach it", "Start from the records your team already maintains. Choose a CRM object and, where useful, a shared smart list. Email, SMS, QCall AI voice and native WhatsApp each support a one-step campaign or a sequence of up to 20 steps. A saved draft uses one channel and one connection, so each step has a clear provider and contact address.", "An administrator reviews the exact eligible audience before launch. Marketing consent, valid addresses, deduplication and channel suppressions are checked again before each send. Each launch currently supports up to 500 contacts. Narrow a smart list for a larger audience."], ["Keep control after launch", "Published steps stay fixed. Pause, resume or cancel queued and future work, or stop an individual contact. Durable waits share the workflow runtime with CRM and finance, and activity links back to execution history. Configurable daily and hourly connection limits apply across campaigns and WhatsApp AI replies.", "SMTP with optional IMAP, Google and Outlook can detect matched email replies. WhatsApp receives incoming text and signed delivery/read updates. SMS and voice expose provider acceptance; reply callbacks are not connected. When provider acceptance is uncertain, inspect the provider result before retrying."], ["Connect the account your team uses", "Add a private SMTP connection or authorize Google or Outlook. For SMS, paste a single HTTPS POST cURL with its JSON body and map the recipient and message fields. For voice, use your QCall account and choose an assistant and dialer. For WhatsApp, connect your Business Cloud API phone and approved templates.", "Provider account approval, mailbox permissions, WhatsApp templates and provider usage fees remain separate from your DryKraft subscription. Optional WhatsApp AI text replies use your configured language model within an incoming 24-hour conversation window. Review the business instructions and preview the response before enabling it."]],
  crm:[['Keep follow-up close to the record','A CRM record should help the next person continue the conversation. Store a person’s contact information, relate a deal to that person, and record notes and tasks against the customer record. Your team can see the relevant details without reconstructing the relationship from separate spreadsheets. Leads have their own source, status, score and potential value. When a lead is ready, conversion creates a contact record and you can add a connected deal; a matching email helps avoid creating another person for the same contact.','Start with a few fields your team will actually keep current. An account manager may need an owner and next action, while another business needs service type or renewal month. Administrators can add those fields to the existing object. For a separate kind of work, create a custom object with its own definition. Search and table columns make the workspace easier to scan as records accumulate.'],['Bring existing records into the workspace','Import a UTF-8 CSV file, map its columns to CRM fields, and check the preview before applying it. The importer validates the full file first. For people, matching workspace email addresses can be skipped, updated or flagged as duplicates. Blank update cells preserve existing values. This is useful when moving a small customer list out of a spreadsheet or updating a known set of contacts. Each import currently supports up to 500 records and a 300 KB file. Owners and administrators can also select two people and review a contact merge. Choose the remaining details before confirmation; notes and relationships follow the remaining contact, while issued financial history keeps its original details. Marketing consent remains enabled only when both contacts already consent. Source follow-ups stop, although a provider request already submitted may finish. There is no restore action for a merge.','Create a count widget for leads by source, or group customers by a field that matters to your team. Monetary reports use one currency at a time. Keep the dashboard focused on a question that someone can act on, then connect the next step with a workflow.']],
  sales:[['Make the pipeline describe real work','Pipeline stages are most useful when the team agrees on what each stage means. Create a pipeline, name its stages and set their probabilities around your sales process. A deal holds its company context, linked person, owner, value, currency and expected close date. Move it on the board or open the record and select a stage directly. The stage is visible to the team alongside the details needed for the next conversation.','Open Stage history on a saved deal to see its recorded path, from/to stage and pipeline, actor and time. Names are preserved at each move, so later renames do not rewrite earlier entries. New deals record their first stage; earlier moves are not reconstructed. A stage or pipeline change can also trigger a shared workflow. Use tasks to capture follow-up work instead of treating a stage as a reminder. A proposal may need a review, a call or a revised scope. Keep that task with an owner and a date so the next action is clear. Different pipelines can represent different processes; they do not need to share an identical set of stages.'],['Keep values useful through the handover','A deal amount only has meaning with its currency. DryKraft keeps values in the currency recorded on each deal and separates financial totals by denomination. Choose a currency for dashboard sums and averages. Changing the workspace default affects new records; it does not convert past deal values or combine USD and INR into a single total.','When a deal is won, its customer context can continue into finance. A shared workflow can create an invoice draft for review. Check the customer, dates and line items before issuing it. The handover stays explicit: marking a deal won does not collect money or send a customer a message.']],
  finance:[['Review the invoice before it becomes final','Set your issuer name, address and invoice details in Finance settings, then create a draft linked to the customer or deal. Add line descriptions, quantities, unit prices, discounts and tax rates. Check the invoice currency and due date before issuing. Issuing assigns a unique number and freezes the invoice details, including the issuer information used on that invoice. Download the PDF for your normal customer communication process.','Record payments that have already been received, with a date and reference. An invoice can have partial payments, and its balance reflects the recorded entries. Review open and overdue invoices in the finance views. An unpaid issued invoice can be voided by an administrator where appropriate. These actions preserve a visible trail rather than silently editing an issued document.'],['Give expenses an approval path','An expense starts as a draft with the vendor, date, category, currency, amount, included tax and a receipt reference. Submit it for review once the details are ready. An administrator can approve or reject the submitted expense. After approval, an administrator records a payment date and reference when the expense has been paid. The finance workflow separates capture, approval and payment recording so each decision has a clear place.','Enable the currencies your team uses and retain each entry’s original currency. KWD uses three decimal places; USD, INR and EUR use two. Finance events and draft creation use the same workflow builder as CRM. Payment collection, bank reconciliation and automatic invoice delivery require provider connections that are not available in this release.']],
  automation:[['Choose the trigger and the next useful action','Start with a record event, webhook, schedule or manual trigger. A workflow can check a condition, create or update a CRM record, create a finance draft, wait or record a log entry. For example, a newly qualified lead can create a follow-up task, while a won deal can create an invoice draft. Choose a specific next action and supply the values it needs instead of trying to automate the entire business process in one graph.','Schedule steps can repeat at an elapsed interval or use a calendar pattern in a named timezone. Daily, weekday and Monday presets sit alongside custom cron expressions. Preview the next five times before publishing. After downtime, one overdue run queues and other missed times are skipped; reactivation starts at the next future time. The visual canvas shows the path. Step and connection selectors also let you configure the graph without dragging. Conditions have separate yes and no paths. Switch routes the first matching case or a default. Loop runs its Each item path sequentially and its Completed path once. It snapshots the list, scopes item values and records each iteration separately; empty input skips the item steps. Up to 1,000 items, five nested Loops and 10,000 visited steps per execution, with explicit input/output limits. List steps can filter, map, sort, limit, deduplicate and aggregate JSON arrays, with explicit item/output limits; inspect their saved results before using them in the next action. Invalid field-value JSON remains visible in the editor and must be corrected before saving, so an accidental edit does not silently fall back to an earlier value.'],['Publish deliberately and inspect the result','Save the workflow as a draft while you configure it. Publishing creates a version used by executions, so later draft edits do not change a run already attached to that version. Execution history shows the run state and individual step results. Use that evidence to check what happened before expanding the workflow to more events or records.','Waits and retries keep saved execution state. From execution details, review replay of the current failed step and exact Loop item while retaining completed outputs, or review a full rerun using the original published version and input. A full rerun starts again and can repeat records or external requests; check uncertain provider outcomes first. Recovery history links the original and repeated runs. Managed outreach remains under its campaign controls. Pausing a workflow stops new activation while retaining its configuration. HTTP and GraphQL actions use configured credentials and the platform’s network protections; a provider account and its permissions still have to be supplied. GraphQL uses JSON POST, a 20-second request limit and a 1 MB response limit. Errors stop the step by default; an explicit partial-data setting can continue a response with data and errors. Subscriptions, streaming, file uploads and automatic pagination are not included. Mutations can repeat on retry when a destination does not honor the supplied idempotency key. An execution log is evidence of the configured action, not proof that an unconnected messaging or payment provider has delivered anything.']]
};
function detailSections(key) {return `<section class="detail-content section">${moduleContent[key].map(([title,...paragraphs])=>`<article><h2>${title}</h2><div>${paragraphs.map(text=>`<p>${text}</p>`).join('')}</div></article>`).join('')}<a class="text-link" href="${key==='calendar'?'/docs/product/calendar':key==='finance'?'/guides/invoices-and-expenses':key==='sales'?'/guides/multi-currency':key==='crm'?'/guides/crm-setup':key==='outreach'?'/docs/product/outreach':'/docs/product/automation'}">${key==='calendar'?'Read the calendar and booking guide':key==='finance'?'Read the invoice and expense guide':key==='sales'?'Understand currency-aware reports':key==='crm'?'Read the CRM setup guide':key==='outreach'?'Read the campaign and sequence guide':'Start your first workflow'} ${arrow}</a></section>`;}
function productPage(page,app) {
  if(page.path==='/product')return `<section class="page-hero"><h1>${page.title}</h1><p>One place for the customer story, the sales process and the work that follows.</p>${actions(app)}</section><section class="section compact">${moduleLinks('h2')}</section><section class="split section"><div><h2>Connected by design.</h2><p>Your records are the shared starting point. Dashboards help you follow the business. Workflows help you act on changes across CRM, sales and finance. Outreach uses the same customer audience and execution history for email, SMS, AI voice and WhatsApp. Calendar keeps customer appointments and booking availability connected to the next action.</p><a class="text-link" href="/product/automation">Explore workflows ${arrow}</a></div>${preview('automation')}</section><section class="detail-content section"><article><h2>Start with the customer. Keep the handover connected.</h2><div><p>A lead captures the first enquiry and its source. People and companies keep contact details and business context. When the opportunity is ready, conversion creates a contact record and you can add a connected deal. Sales gives that deal an owner, stage, value and expected close date. Tasks keep follow-up visible alongside the work.</p><p>Finance continues the story with invoice drafts, issued documents, payment records and expense approvals. A shared workflow can respond to supported CRM and finance events, create an internal task or generate an invoice draft. Drafts still have a clear place for human review before they become issued documents. Outreach continues the conversation through a connected mailbox, SMS provider, QCall voice assistant or WhatsApp Business phone. Campaigns and sequences use the same consenting CRM audience and shared execution history.</p><p>Each module is available from the thin primary rail in the application. Its second menu opens the relevant overview, records, reports and settings. That structure gives the team a clear place to work without asking it to navigate a single long list of unrelated pages.</p></div></article><article><h2>Make the workspace useful to your team.</h2><div><p>Configure custom objects and fields around the information the team maintains. Choose the table columns that make records easy to scan. Create dashboards with counts, sums, averages, groupings and filters. Currency-aware monetary widgets keep unlike denominations separate, while counts help you understand the work across records.</p><p>Save reusable invoice designs, expense defaults and outreach message templates in your workspace. Edit the content, apply a copy to a draft and review it before issuing or launching. Previously issued invoices and launched outreach keep their original content. Invite teammates to the existing workspace with administrator, member or read-only access. Owners retain control over administrator grants. Workspace settings manage the company name, timezone and enabled currencies. These controls share the same workspace rather than creating separate customer applications.</p><a class="text-link" href="/product/customization">Explore fields and dashboards ${arrow}</a><br><a class="text-link" href="/product/team-access">Explore team roles and invitations ${arrow}</a></div></article><article><h2>Connect your systems with explicit access.</h2><div><p>Create a service account for each integration and approve only the objects and actions it needs. Named, expiring keys use the versioned CRM API and retry-safe writes. Record changes and internal notes remain connected to the shared event and audit history.</p><p>Review scopes before granting a key, then rotate or revoke it when access changes. A key cannot sign in to the app or manage billing and outreach providers. Reading an approved object includes every field; fine field and team policies remain separate work.</p><a class="text-link" href="/product/developer-access">Explore developer access ${arrow}</a></div></article></section>${channelLinks()}${faq()}`;
  const key=page.path.split('/').at(-1),d=productDetails[key];
  return `<section class="hero product-hero"><div class="hero-copy"><h1>${page.title}</h1><p>${d.intro}</p>${actions(app)}</div>${preview(key)}</section><section class="feature-editorial section">${d.steps.map(([title,text])=>`<article><h2>${title}</h2><p>${text}</p></article>`).join('')}</section>${detailSections(key)}${key==='outreach'?channelLinks():''}${key==='finance'?'<section class="release-note"><strong>A clear distinction.</strong><p>Payment entries record money already received or paid. Payment collection, bank reconciliation and automated invoice delivery need provider connections.</p></section>':''}<section class="next-module section"><h2>${d.follow}</h2><a class="button secondary" href="${d.next}">See how it connects ${arrow}</a></section>`;
}
function guides(app) {
  const topics=[['Your workspace','Create your account with your name, email and password. In the onboarding step that follows, choose an available workspace address and a default currency and enable the currencies your company uses. Workspace settings let administrators update the name, currencies and timezone.'],['Your customer records','Open CRM to add people, companies and leads. Add a note or task to keep the next step visible. Use Objects & fields in Settings to add the details your business needs.'],['Your sales pipeline','Open Sales to create and arrange pipeline stages. Add deals with a contact, owner, expected close and currency. Move a deal as the conversation progresses.'],['Your first invoice','Set your issuer details in Finance settings. Save a draft with customer details, line items, discounts and taxes. Review it before issuing; issued details are locked. Download the PDF and record payments already received.'],['Your expense approvals','Save an expense with vendor, date, currency and amount. Submit it for administrator review. An approved expense can be marked paid with a payment date and reference.'],['Your first workflow','Create a draft in Automate, or start with a Finance workflow template. Configure the trigger and actions, save and review the graph, then publish to activate it. Execution history shows the results.'],['Your outreach','Connect a mailbox, SMS provider, QCall account or WhatsApp Business phone in Outreach - Connections. Create a campaign or sequence, choose a CRM audience, save a draft and review eligible consenting contacts before launch. Provider acceptance is separate from delivery. See the product documentation for channel setup and reply behavior.'],['Your team and account','Create invitation links in Settings - Team members and share them through your usual channel. Check active devices in Account security. The owner can review trial access, seat counts and Enterprise requirements in Billing.'],['Your dashboard','Select Customize in the overview. Add a widget, choose its object and calculation, then choose the display and filters. Select one report currency for monetary totals.']];
  return `<section class="page-hero"><h1>Get started<br>with DryKraft.</h1><p>A practical guide to the first things you can do in DryKraft.</p><a class="button primary" href="${escape(app)}/signup">Create your account ${arrow}</a></section>${resourceLinks()}<p class="guide-docs-link"><a class="text-link" href="/docs">Open complete product documentation and API reference ${arrow}</a></p><section class="guide-layout section"><nav aria-label="Guide topics">${topics.map(([title],i)=>`<a href="#guide-${i}">${title}</a>`).join('')}</nav><div>${topics.map(([title,text],i)=>`<article id="guide-${i}"><h2>${title}</h2><p>${text}</p></article>`).join('')}</div></section>${faq()}`;
}
const extraFeatures={
  'developer-access':[['Give each integration its own identity','Owners and administrators create named service accounts in Settings - Developer access. Choose the current workspace objects and actions that the integration needs, then approve with your current password. Read includes every field and owner in an approved object. Newly created objects are not granted automatically.','Each key has its own name, narrower permissions and expiry. Its secret appears once, hidden until you choose to show or copy it. Store it privately on the server that runs the integration. It cannot sign in to the application, manage billing or configure outreach providers.'],['Keep CRM changes consistent','Use the versioned REST API for people, companies, leads, opportunities, tasks and approved custom objects. Read schemas and records, create or update permitted records, or add an internal note. Mutations require an idempotency reference so an identical retry returns the original result without duplicating work. Record changes and notes use the shared audit and event runtime.','Financial objects allow reading and internal notes through this API. Invoice issuing, expense approval and payment recording remain in their dedicated workflows. The API supports up to 120 requests per minute per key alongside the application’s general limit.'],['Reduce or end access deliberately','Rotate a key to issue a replacement and revoke the old credential together. Revoke a key, or disable its service account, to block future requests after in-flight work completes. Reducing an account’s permissions also narrows its existing keys; expanding the account later does not silently restore those grants.','Request history shows normalized operations and status codes without credentials or customer payloads. History is written after a response, so a process interruption can omit a terminal row; authenticated usage is metered before dispatch. SDKs and fine field or team permission policies are not included in this release.'],['Notify your systems about committed events','Open Settings - Webhooks to choose a public HTTPS receiver and the future business events it may receive. Each request carries an immutable event envelope with record IDs and timing, signed with a secret shown once. Customer field values and message bodies stay out of the notification; a separately scoped API key can read authorized current records.','Inspect delivery history and completed attempts when a receiver fails. DryKraft retries up to five attempts, then disables the endpoint. Fix and re-enable the receiver before deliberately replaying a failed delivery. Retries and replay can repeat work, so verify the raw-body signature and deduplicate each delivery ID. Rotate signing secrets with current-password approval and prepare the receiver for the replacement.']],
  "email-outreach":[["Connect the mailbox you already use", "Authorize Google or Outlook for sending and inbox access, or enter an SMTP host, port and private login. SMTP connections support TLS on ports 465 or 587; optional IMAP reply detection uses port 993. Native mailbox authorization requires the provider app and callback configuration. This connects a mailbox; it is separate from signing in to DryKraft.", "Google and Outlook permissions are granted in their own consent flow. A saved connection alone is not proof that sending is ready. Verify and enable the connection, then review the audience before launch. Private credentials stay encrypted per workspace."], ["Write the campaign or the follow-up sequence", "Use CRM fields to personalize a subject and message. A campaign sends one step; a sequence can schedule up to 20 steps with waits. Review Marketing consent and the exact eligible addresses, then launch through a verified connection. Configured daily and hourly limits apply across runs.", "Email includes an unsubscribe link and one-click unsubscribe headers. Google, Outlook and optional IMAP check recent inbox messages for matching references and sender addresses. A detected matched reply stops follow-ups. Reply checks run about every five minutes."], ["Inspect acceptance and know the limits", "Activity records provider acceptance and links to the shared execution history. It does not promise inbox delivery, opens or clicks. Open/click tracking and bounce processing are not connected in this release. If a send result is ambiguous, inspect the mailbox provider before attempting another send.", "Read the email guide for configuration, reply matching and credential handling."]],
  "sms-outreach":[["Start with your provider request", "Paste one send-message cURL supplied by your SMS provider. DryKraft reads its HTTPS POST URL, headers and JSON body; it does not execute a shell command. Choose which body fields hold the recipient and message or template variable. MSG91-style recipient arrays are supported with a mapped single-recipient path.", "Only public HTTPS destinations on port 443 are accepted. File input, shell expansion, redirects and multiple recipients on the mapped array path are rejected. Validation confirms request shape; it does not confirm your provider login or guarantee message delivery."], ["Build a campaign or sequence", "Choose the SMS connection and a CRM audience, then write the message or configure template variables. Contacts need Marketing consent and a valid international phone number. An administrator reviews the current eligible audience before launching; suppressions and limits still apply before every step.", "A campaign sends one step. A sequence supports up to 20 steps with durable waits. Use your provider’s approved template and variable names where required. Provider policies and per-message usage fees remain separate."], ["Follow the result at its actual scope", "SMS activity records provider acceptance and failed or uncertain attempts. Delivery receipts and incoming SMS replies are not connected in this release. Pause or cancel future work from the sequence, and inspect provider logs before retrying an uncertain result.", "The SMS setup guide includes parameter mapping and supported request boundaries."]],
  "ai-voice":[["Connect your QCall account", "Enter the API ID for your workspace’s QCall account and verify the connection to load its available assistants and dialers. Select the assistant and dialer that should handle the outreach. Production workspaces use their own provider account.", "Assistant behavior, phone configuration, account permissions and usage costs are managed with QCall. Reading the available choices confirms account access; it does not place a call."], ["Keep calls tied to the CRM audience", "Choose consenting records with valid international phone numbers. Configure the contact variables and a one-step campaign or up to 20-step sequence. Review the eligible audience and launch through an enabled connection. Each step creates the provider contact/tag and requests its automated campaign.", "Durable execution state and per-connection hourly/daily limits govern scheduled work. Pausing or cancelling stops future queued steps; it cannot retract a call already accepted by the provider."], ["Separate acceptance from the call outcome", "DryKraft records the provider request result and links to its workflow execution. Voice reply callbacks and automatic conversation-outcome synchronization are not connected. Inspect QCall for actual call progress and outcomes. An uncertain acceptance requires provider inspection before retrying.", "The AI voice guide explains assistant/dialer selection and the current integration boundaries."]],
  "whatsapp":[["Connect a WhatsApp Business phone", "Use your Business Cloud API access, WABA ID and phone-number ID. Verification checks that the phone belongs to that business account. Configure the connection-specific callback and signing details for incoming text and delivery updates.", "Start outreach with an approved WhatsApp template. Current templates support text body parameters; dynamic header and button parameters are not supported. Approval, account access and WhatsApp usage fees remain with the provider."], ["Follow the conversation and its delivery state", "Choose an eligible consenting CRM audience for a template campaign or sequence. Signed callbacks add delivery/read states and incoming text to activity. Incoming replies stop future follow-ups, while STOP and equivalent requests permanently suppress that channel for the contact.", "Delivery is distinct from acceptance. Callback processing deduplicates messages and preserves ordered receipt states. Configure the Meta callback before relying on live receipt or incoming-reply behavior."], ["Add optional AI text replies", "Enable business instructions for replies powered by your configured language model. Preview a response before enabling automation. The connection shows which incoming text and business instructions are sent to the model. AI replies are limited to an incoming 24-hour conversation window.", "AI cannot execute tools or grant workspace access. Limits are shared with campaign sends, and follow-ups respect opt-outs. This release does not include a conversation handoff inbox."]],
  "account-security":[["Add a second step to sign-in","Enable an authenticator from Account security, confirm its six-digit code and save ten recovery codes privately. Sign-in then requires your password and an authenticator code or unused recovery code before opening your workspace.","Recovery codes work once. You can replace them or turn off verification with your current password and a fresh authenticator or recovery code. These changes end older sessions; your current browser receives a new session."],["See where your account is signed in", "Open Settings - Account security to separate this device from other sessions across all your workspaces. Browse other sessions in groups of 25, with approximate browser labels, creation time, recent activity and expiry. Activity updates about every five minutes; browser labels are not identity or location proof.", "Sessions last up to seven days. End one other session or all other sessions after reviewing the confirmation. Ending this device signs it out. Workspace membership removal separately revokes that workspace’s sessions."], ["Change a password with a clear outcome", "Your current password and matching new entries are required. A successful change rotates this session and ends all other account sessions. New passwords contain 10 to 128 characters, and account-scoped attempt limits apply. The shared sample account cannot change its password.", "Private security history shows the latest 20 successful password and session changes initiated here. It is personal account information, separate from the workspace business audit log."], ["Use the controls available today", "Owners and administrators manage team access through invitations and workspace roles. Session review and password controls protect personal access without changing the customer records that teammates share.", "Password reset by email is available from the sign-in page. Reset links expire after 15 minutes, work once and end existing sessions; email verification, OAuth account login and magic links are not available in this release. Developer access provides separately scoped service accounts and expiring API keys for versioned CRM integrations. Native Google and Outlook outreach connectors authorize mailboxes; they do not provide account login."]],

  customization:[['Make the workspace reflect the work','Your CRM should describe the information your team needs to keep. DryKraft starts with people, companies, leads, deals and tasks. Administrators can extend those objects with fields or define a custom object for a separate type of record. Give each field a clear name and choose a type that matches the information: text, a number, a date, a selection, a workspace member, a relationship or a monetary value. Required fields make the expectation explicit when a record is saved. Workspace member fields let you assign a current teammate by name while keeping a stable reference for imports and automation.','A useful field is one your team understands and maintains. Before adding it, decide who will update it and what decision it helps someone make. Existing objects keep their records when you add optional fields. Choose table columns around the task at hand so important context remains visible without opening every record.'],['Build dashboards around a question','Create a dashboard and add widgets that count records, sum amounts or calculate an average. Choose an object, a grouping field and an appropriate display: a metric, bar chart or donut. Filters let a widget focus on a particular part of the data, such as an owner or status. Keep a report specific enough to guide an action. A lead count by source can help a team review where new conversations begin; a task count by status can show where follow-up needs attention.','For financial widgets, select a report currency. DryKraft does not turn unlike currencies into a misleading combined amount. A change to the default currency affects new records, while existing values retain their original currency. KPI definitions are saved per workspace. Edit a widget later, choose fixed or rolling dates using a record timestamp or date field, and download the saved dashboard’s current results as a labeled CSV report. Timestamp dates use the workspace timezone. Reports include currencies, filters and resolved dates, with up to100 groups per widget; raw-record exports and scheduled report delivery remain separate work.'],['Configure the shared process','Sales pipelines can have their own stages and probabilities. Workspace administrators manage company settings, enabled currencies, timezone and team access. Workflows connect record events to the next action across CRM, sales and finance. These settings are part of the same workspace, so configuring the process does not require a separate application for each customer.','Start with the smallest configuration that helps the team complete its work, then add fields and reports as the need becomes clear. Customization is available through defined objects, fields, dashboards and workflow controls. Arbitrary code plugins, a customer theme editor and advanced field-level permission rules are not part of this release.']],
  'team-access':[['Invite people into the existing workspace','A team should share one customer record and one view of the work. Owners and administrators can create an invitation for a specific email address and copy its link to share through their usual channel. Invitation links expire after seven days. Creating a replacement link invalidates the earlier one, and pending invitations can be revoked. No email delivery provider is configured in this release, so generating a link does not claim to have sent an email.','The invited person can sign in to an existing account or create an account through the invitation. Accepting joins the workspace named in that invitation; it does not create a second company workspace. A person with access to more than one workspace can switch between the workspaces available to their account.'],['Choose a role around the person’s task','Administrators manage workspace settings, workflows and member access. Members create and update business records, dashboards and workflow drafts. Read-only teammates view the workspace without making changes. Owner access is protected, and only owners can grant or manage administrator access. These distinctions give the team a clear starting point without asking every user to configure a permission system.','Role updates check that the membership has not changed since it was loaded. Removing a teammate revokes that person’s sessions for the workspace while preserving business records. Existing customer information and finance history are not deleted because a team member leaves. Settings - Teams & locations also lets administrators group current teammates, choose a team lead and associate a team with an office. Locations retain address and timezone details with separate direct member assignments. Archive and restore groups without losing their saved details. Grouping does not grant extra access or add billable seats. See the <a href="/docs/product/teams-locations">teams and locations guide</a> for setup and archive rules.'],['Keep administration visible','The workspace audit log records supported business and team changes, including invitation and membership events. Those events can also be selected in the shared workflow builder. Customer workspace records stay isolated from other tenants at the request and database layers. Choosing a workspace address gives the team a recognizable company identity during setup.','Use an administrator account for configuration and a member or read-only role where that fits the work. Fine user object-level and field-level permission rules, ownership transfer, account recovery, OAuth and magic links remain outside the current release. Review the available roles before bringing a larger team into the workspace.']]
};
function featurePage(page,app) {const key=page.path.split('/').at(-1);return `<section class="page-hero"><h1>${page.title}</h1><p>${escape(page.description)}</p>${actions(app)}</section><section class="detail-content section">${extraFeatures[key].map(([title,...paragraphs])=>`<article><h2>${title}</h2><div>${paragraphs.map(text=>`<p>${text}</p>`).join('')}</div></article>`).join('')}</section><section class="next-module section"><h2>Start with your workspace.</h2><a class="button secondary" href="${key==='customization'||key==='team-access'?'/guides/crm-setup':key==='developer-access'?'/docs/product/developer-access':key==='account-security'?'/docs/product/team-security':'/docs/product/'+({'email-outreach':'email','sms-outreach':'sms','ai-voice':'voice',whatsapp:'whatsapp'}[key])}">Read the setup guide ${arrow}</a></section>`;}
const articles={
  'outreach-setup':{intro:'Start with a small audience that expects to hear from you. A useful first campaign makes its recipients, message and sending account easy to review.',sections:[['Connect the channel you will use','As a workspace owner or administrator, open Outreach - Connections. Email can use an SMTP mailbox with optional IMAP reply detection, or a native Google or Outlook connection. SMS uses your provider’s HTTPS POST cURL with a JSON body; map the recipient and message parameters after parsing it. Parsing validates the request structure without sending a message.','For AI voice, connect your QCall account and choose an available assistant and dialer. For WhatsApp, connect the Business Cloud API phone number and account, configure callbacks and choose an approved template. Optional WhatsApp AI text replies use your configured language model, within an incoming 24-hour conversation window. Provider permissions, template approvals and usage charges remain part of your provider account.'],['Choose consenting contacts and a clear message','Create a campaign for one step or a sequence for up to 20 steps in one channel. Select the contact object and, when useful, a saved smart list. Narrow the source to at most 500 contacts. Marketing consent must be enabled, and each contact needs a valid email or an international phone number with its country code. Duplicate addresses and suppressed recipients are excluded.','Write an email subject and message, SMS text or template variables, a QCall call step, or WhatsApp template body parameters. Use the actual CRM field keys for personalization, such as {{record.data.name}}. Add waits before sequence steps when the conversation needs space. A sequence stays in its chosen channel; it does not switch from email to SMS automatically.'],['Save, review and deliberately launch','Save the draft before opening Review audience. Inspect the eligible recipients and exclusion reasons, then check the saved content and connected account. Reviewing sends nothing. Launch outreach is a separate administrator action that queues real messages or calls. If the draft or audience changes, review it again.','Use a verified, enabled connection and conservative sending limits for your first launch. Published steps and enrolled contacts stay fixed. New people matching a smart list are not added silently. Duplicate a campaign into a new draft when you need a different message or audience.'],['Read the result before the next attempt','Activity distinguishes provider acceptance from confirmed delivery. WhatsApp signed receipts can report delivery and read states. Email, SMS and voice acceptance does not prove that the recipient read a message or completed a call. An Unknown outcome needs investigation with the provider before another attempt.','Pause or stop future follow-ups when needed. Matched email replies and WhatsApp incoming text stop the remaining steps; SMS and voice reply tracking are not available. Suppress a recipient to block further outreach on that channel. A message or call already accepted by a provider cannot be recalled.']]},
  'first-workflow':{intro:'Begin with one visible outcome: a task created in your CRM. Follow that work through execution history before connecting a workflow to everyday business changes.',sections:[['Choose a small outcome you can check','Open Automate - Workflows and create a named draft, such as First follow-up task. The new canvas starts with a Manual trigger. Choose Add step, then Create record, and select Tasks in the Object field. In Field values, enter a JSON object such as {"name":"Example follow-up task","status":"To do"}.','Select Manual trigger from Select a workflow step and check that Next step points to Create record. You can also connect the canvas handles. Use fictional test information and an internal action for this first workflow. Record creation follows the same field and relation validation as creating a record by hand.'],['Save the draft and publish a version','Choose Save draft. Before Publish, check the task object, action data and connection between nodes. An owner or administrator publishes the workflow; publishing validates the settings and preserves a version for executions. A workflow needs exactly one trigger and all nodes connected to it.','A saved draft and a published workflow are different states. Later draft edits do not change the version used by a run. Save and publish again when the reviewed behavior needs to change. Managed outreach workflows remain controlled through Outreach, where audience review and launch checks apply.'],['Run it and inspect both sides','Choose Test run, leave Trigger input as {} for this example, and confirm Run published version. This performs real actions in your workspace. Open Execution history and inspect the state and step results. If it succeeds, open CRM - Tasks and confirm that Example follow-up task is present.','If the run fails, read the step error and check the action’s fields and context. Missing expression paths become empty strings, so inspect inputs rather than assuming a value exists. Correct the draft and publish its replacement. For external requests with an uncertain outcome, check the provider before another attempt.'],['Connect the next business event','After the manual path works, consider a business-event trigger such as a newly won deal. Event workflows can use record context, including {{record.data.name}} and {{record.id}}. Conditions select a path and waits preserve a delayed next step without holding a worker open.','A finance action creates a draft for review; it does not issue an invoice or move money. Pause controls future triggering, while cancelling an unfinished execution controls that run. An accepted external action cannot be undone by cancelling. Keep each workflow small enough that the next teammate can understand its trigger and outcome.']]},
  'team-and-security':{intro:'A teammate needs the access required for their work. Your own account also needs a clear view of where it is signed in. Manage those two responsibilities from Settings.',sections:[['Choose the workspace role first','Open Settings - Team members as an owner or administrator. Choose whether the person needs record editing, read-only access or administration. Only the owner can grant or manage administrator access. Owner access is protected, and the current release uses workspace roles rather than custom permissions for every field.','Every workspace member counts as one billing user, including the owner and read-only members. Pending invitations do not count. An active subscription needs enough available seats when a new teammate joins. Check the team size in Billing before planning a larger rollout.'],['Share an invitation with the intended person','Create an invitation for the teammate’s email address and share the copyable link with them. Invitations expire after seven days. Creating a replacement invalidates the earlier link. DryKraft does not automatically send an invitation email in this release.','The invited person signs in or creates an account and joins this workspace, rather than creating another company. Cancel an unused invitation when it is no longer needed. A link does not substitute for deciding the person’s role or checking the email address before sharing.'],['Review and remove access when work changes','Review the member list after a teammate joins. Use the available role controls when their responsibilities change. Removing a member ends their workspace sessions while preserving the business records they worked on. Refresh if a teammate’s membership changed before your save.','Supported invitation and membership changes appear in the workspace audit trail. This is separate from the private history of password and session changes on your own account. Workspace administration does not expose another person’s private account security history.'],['Inspect your own signed-in sessions','Open Settings - Account security or choose it from the account menu. Review this device and other sessions across your workspaces, including sign-in, activity and expiry information. Browser labels are approximate; they do not prove a physical device or location. Sessions expire after seven days and activity updates roughly every five minutes.','End an unfamiliar session through its confirmation, or end all other sessions when appropriate. Changing your password requires the current password and matching new entries, and ends other account sessions. Ending this device signs you out. Email recovery and multi-factor authentication are not available in this release.']]},
  'trial-and-billing':{intro:'Explore the workspace before committing to a subscription. Keep the team’s subscription seats separate from the currencies and payment records used in your business.',sections:[['Start the trial after account signup','Create your account first, then complete workspace setup with its name, address and currencies. The 15-day trial starts when the workspace is created. No card is required for the trial, and account signup does not automatically charge you.','Use the trial to add records, inspect the finance workflow, build a small automation and review provider setup. When trial access ends, records remain readable. An active plan is needed for most business changes and automated work; account security and billing remain available.'],['Count the people who need access','Each active workspace member uses a seat, including the owner, administrators and read-only members. Pending invitations are excluded. Review the current seat count and subscription details in Settings - Billing.','The owner chooses subscription seats in Settings - Billing. Choose at least enough seats for current members and plan for additional teammates. Record currencies such as INR, EUR and KWD are separate from subscription billing. Connected email, SMS, voice and WhatsApp providers can charge separately for their usage.'],['Review hosted checkout and manage renewals','Continue from Billing to Dodo Payments hosted checkout and review the final amount and taxes before committing. Adding payment details during the trial preserves the remaining free days, rounded up to the whole-day units used by Dodo. Returning to DryKraft alone does not establish a paid subscription; provider confirmation updates its status.','Use Refresh billing when a provider update is pending. Once subscribed, the Dodo portal handles payment methods, subscription invoices and cancellation. Seat changes take effect immediately without an immediate charge, and the new monthly price applies at the next renewal. Remove members before reducing seats below the current member count.'],['Keep Enterprise and customer payments clear','Enterprise requirements and scope can be discussed with support@drykraft.com or saved from Billing. Submitting a request does not activate an agreement, paid plan or extra features.','Dodo processes the subscription your company pays for DryKraft. Payments recorded against your customer invoices in Finance represent money already received elsewhere. Recording an invoice payment does not transfer money, collect from a customer or reconcile a bank account.']]},
  'crm-setup':{intro:'Build a useful starting point for your customer relationships. Begin with the records and fields that help someone take the next step.',sections:[['Create the account, then the workspace','Sign up with your name, email and password. Your account is created before workspace configuration. In the next onboarding step, enter the company workspace name and choose an available address. Addresses start with a letter and use 3-40 letters, numbers or hyphens. Choose a default currency and enable the others your company works in. If you stop partway through, signing in again returns you to setup.','Workspace administrators can later update the name, timezone and currencies in Settings. The address identifies the workspace; it does not automatically connect an email service, payment provider or custom domain. Use the workspace switcher if your account belongs to more than one team.'],['Start with people, companies and leads','Add the customer details the team will need to continue a conversation: a name, contact information, company context and owner. Keep leads separate while they are being qualified. Record the source and status so another person can understand why the lead is in the workspace. When it is qualified, conversion creates a contact record and you can add a connected deal and checks for a matching person email.','Add notes where the conversation happened and create a task when a concrete follow-up is needed. A task with an owner and date is easier to act on than an unstructured reminder. Keep fictional sample data separate from the records your team imports.'],['Import an existing customer list carefully','Prepare a UTF-8 CSV file with a distinct header for each column. Imports currently accept up to 500 records and a 300 KB file. Open the relevant CRM object, choose Import, select the file and map each source column to the correct field. Review the preview and validation results before applying the import. For people, decide whether matching emails should be skipped, updated or reported as duplicates.','Blank cells in an update preserve existing values. Invalid rows are reported before an import is applied, and applying a valid import is transactional. Start with a file whose contents you can review; keep the source spreadsheet until you have checked the resulting records.'],['Add only the fields your process needs','Open Objects & fields in Settings to extend an existing object or create a custom one. Choose a type that represents the value and give the field a label your teammates will recognize. Then adjust table columns so the most useful information is visible. Use a dashboard count, grouping or filter to answer a question about those records.','Invite teammates with the role that fits their work. A read-only teammate can review records, while a member can create and update business data. Owners and administrators manage the workspace configuration. Agree on which fields the team will maintain before adding more.']]},
  'invoices-and-expenses':{intro:'Keep document preparation, approval and payment recording in a clear order. This guide covers the finance workflow available in DryKraft today.',sections:[['Set the issuer details first','Open Finance settings and enter the details that should appear on your invoices. Review the issuer name and address before creating the first document. A workspace administrator manages this configuration. Issued invoices retain the issuer information used at the time of issue, so a later settings change does not rewrite a document already issued.','Choose the enabled currencies in Workspace settings. The invoice currency determines how amounts are entered and reported. Review taxes and discounts against the actual transaction; DryKraft supports configurable values rather than deciding which tax rules apply to your business.'],['Create and review the draft','Create an invoice draft from Invoices, or use a workflow to generate a draft from a won deal. Connect the customer and deal where relevant. Enter the customer details, invoice and due dates, line descriptions, quantities, prices, discounts, taxes and notes. Check the currency before entering amounts.','Review the saved draft before issuing it. Issuing assigns a unique invoice number and freezes the details. Download the PDF for your own delivery process. Automatic invoice email delivery and payment collection are not connected, so issuing an invoice does not say it was sent or that money was received.'],['Record money already received','When a payment has actually arrived, record its amount, date and reference against the invoice. The balance is updated from the recorded entries. Partial payments can be entered separately, which lets the team follow the remaining amount without replacing the original invoice total.','Use the finance views to review open and overdue balances. A payment entry is a record of a transaction handled elsewhere; it does not initiate a transfer. Bank reconciliation and payment provider collection require connections outside the current release. An administrator can void an unpaid issued invoice when that is the appropriate correction.'],['Submit expenses for review','Create an expense draft with the vendor, date, category, currency, amount, included tax and receipt reference. Save the draft, check its details and submit it for review. An administrator approves or rejects the submitted expense. Rejected work can be corrected through the available workflow rather than marking it paid without approval.','Once an approved expense has actually been paid, an administrator records the payment date and reference. The resulting state distinguishes an amount captured, an amount approved and an amount paid. Finance events can trigger the same workflow builder used by CRM, so a finance change can create an internal task or another configured action.']]},
  'multi-currency':{intro:'A currency setting should keep amounts understandable. Decide which currencies the team uses, then make each report answer a question in a specific denomination.',sections:[['Choose a default and enable the currencies you use','During workspace onboarding, select a default currency for new records and default reports. Enable the other currencies used by your company, such as USD, INR, EUR and KWD. An administrator can change this selection later in Workspace settings. The default must be one of the enabled currencies.','Use the currency code alongside the symbol when there could be ambiguity. Several currencies use a dollar symbol, while their values and denominations are different. A customer or deal amount should carry its currency as part of the record, rather than relying on a teammate to infer it from the company location.'],['Understand what a default change does','Changing the default currency affects the starting choice for new records. It does not convert existing amounts. A deal saved in KWD retains its KWD amount even if INR becomes the new default. Existing records can retain a currency that is later disabled for new work.','This distinction is useful when the team changes its reporting preference or starts working in another market. A historical invoice still needs to mean what it meant when it was issued. Enable a currency before creating new records in it; do not change the default as a substitute for calculating an exchange rate. DryKraft does not perform automatic currency conversion.'],['Enter the right precision for the currency','USD, INR and EUR support two decimal places. KWD supports three, so an amount such as 12.345 KWD is valid while 12.345 USD has too much precision. Invoice calculations use the currency’s minor units, and invalid precision is rejected instead of silently accepting a different amount.','Check the currency before entering invoice prices, deal values or expense amounts. Keep the currency explicit when importing monetary data. A pasted number alone cannot tell the workspace which denomination the original source intended.'],['Keep dashboard totals separate','Select one report currency for monetary dashboard widgets. A sum of INR deal values answers an INR question; a sum of USD deal values answers a USD question. Combining them without an exchange-rate policy would produce a number with no reliable meaning, so DryKraft keeps those amounts separate.','Counts can still answer cross-record questions that do not add money, such as the number of open deals or submitted expenses. For monetary analysis, create separate widgets for the currencies the team needs to review. If your business requires a consolidated amount, establish an exchange-rate source and date policy outside the current automatic reporting capabilities.']]}
};
function articlePage(page) {const d=articles[page.path.split('/').at(-1)];return `<section class="page-hero article-hero"><a class="text-link" href="/guides">All guides ${arrow}</a><h1>${page.title}</h1><p>${d.intro}</p><p class="article-date">Updated October 2, 2026</p></section><section class="guide-layout section"><nav aria-label="On this page">${d.sections.map(([title],i)=>`<a href="#step-${i}">${title}</a>`).join('')}</nav><div>${d.sections.map(([title,...paragraphs],i)=>`<article id="step-${i}"><h2>${title}</h2>${paragraphs.map(text=>`<p>${text}</p>`).join('')}</article>`).join('')}<a class="text-link" href="/product">Explore the connected product ${arrow}</a></div></section>`;}
function about(app) {return `<section class="page-hero"><h1>Business information<br>belongs together.</h1><p>DryKraft is a configurable workspace for customer relationships, sales, finance, outreach and the workflows that connect them.</p></section>${journey()}<section class="detail-content section"><article><h2>The customer story keeps going.</h2><div><p>A customer conversation creates a follow-up task. A qualified lead becomes an opportunity. A won deal needs an invoice, and the finance team needs the customer details behind it. Those handovers are easier to follow when the information stays connected.</p><p>DryKraft brings CRM records, sales pipelines, invoices, expenses and automation into one workspace. A person or company is part of the same business context as the deal and the work that follows. The product is built around that continuity, with a shared data layer and one workflow builder across the current modules.</p></div></article><article><h2>Your process should fit the workspace.</h2><div><p>Teams do not all qualify a lead in the same way, use the same sales stages or measure the same signals. Administrators can define custom fields and objects. Sales pipelines can use the stages the team recognizes. Dashboard widgets can count, sum, average, filter and group the information that matters to the business.</p><p>Customization is most useful when it makes everyday work clearer. Start with a few records and fields that someone will maintain, then add structure as the process becomes better understood. A workspace should help the next person continue the work without having to reconstruct it.</p></div></article><article><h2>Keep the numbers and decisions clear.</h2><div><p>Different currencies keep their own amounts and totals. Changing a workspace default does not convert historical values. An invoice draft can be reviewed before issue, issued details are frozen, and recorded payments represent money already received. Expenses have a separate submission and approval path before payment is recorded.</p><p>Team roles distinguish administration, record editing and read-only access. Supported business and membership changes appear in the audit trail. These product choices make the state of the work explicit: a draft is a draft, an approval is a decision, and a payment entry is a record of a transaction handled elsewhere.</p></div></article><article><h2>What you can use today.</h2><div><p>CRM, sales, finance, four-channel outreach, custom dashboards, team invitations, account security and the shared automation builder are available in this release. Workspace billing includes a 15-day trial and secure checkout. Owners can review subscription details in Billing. The public guides explain the current setup and workflows, including CSV import limits, currency behavior and invoice review. The website previews use illustrative data rather than customer claims.</p><p>Email campaigns connect through SMTP, Google or Outlook; SMS uses your provider request; AI voice connects QCall; WhatsApp uses Business Cloud API and optional AI replies using your configured model. Each connection needs its own provider setup. Broader marketing and social media modules, customer payment collection, bank reconciliation and automatic invoice delivery remain separate work. Product documentation explains the current capabilities and limits.</p><a class="text-link" href="/product">Explore the current product ${arrow}</a></div></article></section><section class="next-module section"><h2>Start with your team’s work.</h2><a class="button primary" href="${escape(app)}/signup">Create your account ${arrow}</a></section>`;}
const channels=[["/product/email-outreach", "Email", "SMTP, Google and Outlook mailboxes with personalisation and matched reply detection."], ["/product/sms-outreach", "SMS", "Your provider’s JSON cURL, with recipient and message parameter mapping."], ["/product/ai-voice", "AI voice", "QCall assistants and dialers, connected to consenting CRM audiences."], ["/product/whatsapp", "WhatsApp", "Approved templates, delivery/read updates and optional AI text replies."]];
function channelLinks(){return `<section class="resource-section section"><div class="section-intro"><h2>Choose how you<br>continue the conversation.</h2><p>Each channel has its own connection, delivery states and provider requirements.</p></div><div class="resource-links">${channels.map(([url,title,text])=>`<a href="${url}"><div><h3>${title}</h3><p>${text}</p></div>${arrow}</a>`).join('')}</div><a class="text-link channel-docs" href="/docs/product/outreach">Read campaign setup and release limits ${arrow}</a></section>`;}
const menuGroups=[{label:'Product',links:[['/product','Platform overview','CRM, sales, finance and workflows'],...modules.filter(m=>m.name!=='Outreach').map(m=>[m.path,m.name,m.text]),['/product/customization','Customization','Your objects, fields and dashboard KPIs'],['/product/team-access','Team access','Invitations, roles and workspace control'],['/product/account-security','Account security','Session controls and private security history'],['/product/developer-access','Developer access','Scoped API keys and versioned CRM integrations']]},{label:'Outreach',links:[['/product/outreach','Campaigns & sequences','Four channels, one CRM audience'],...channels]},{label:'Resources',links:[['/docs','Documentation','Complete product guides and API reference'],['/guides','Getting started','Your first records, invoice and workflow'],['/open-source','Source code','Release status, local setup and ways to contribute'],...guideLinks]}];
function siteNavigation(page,app) {return `<nav id="site-navigation" aria-label="Main navigation">${menuGroups.map(group=>`<details class="nav-group"><summary${group.links.some(([url])=>url===page.path)?' class="current-group"':''}>${group.label}<svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true"><path d="m6 9 6 6 6-6" fill="none" stroke="currentColor" stroke-width="1.7"/></svg></summary><div class="nav-panel">${group.links.map(([url,title,text])=>`<a href="${url}"${url===page.path&&!page.path.startsWith('/docs')?' aria-current="page"':''}><strong>${title}</strong><span>${text}</span></a>`).join('')}</div></details>`).join('')}<a href="/about"${page.path==='/about'?' aria-current="page"':''}>Company</a><div class="nav-actions"><a href="${escape(app)}/login">Sign in</a><a class="button primary small" href="${escape(app)}/signup">Start free trial</a></div></nav>`;}
function siteFooter(app) {
 const groups=[['Product',modules.map(m=>[m.path,m.name])],['Outreach',[['/product/email-outreach','Email'],['/product/sms-outreach','SMS'],['/product/ai-voice','AI voice'],['/product/whatsapp','WhatsApp']]],['Resources',[['/open-source','Source code'],['/docs','Documentation'],['/docs/api','API reference'],['/guides','Getting started'],['/product/customization','Customization'],['/product/developer-access','Developer access']]],['Company',[['/about','About DryKraft'],['/product/team-access','Team access'],['/product/account-security','Account security']]]];
 return `<footer class="site-footer"><div class="footer-inner"><div class="footer-brand"><a href="/" aria-label="DryKraft home"><img src="/logo-ui.png" alt="DryKraft" width="156" height="61"></a><p>CRM, sales, finance and outreach.<br>Calendar and workflows, together.<br>One workspace for your team.</p><a class="footer-support" href="mailto:support@drykraft.com">support@drykraft.com ${arrow}</a></div>${groups.map(([title,links],i)=>`<nav class="footer-links" aria-labelledby="footer-group-${i}"><h2 id="footer-group-${i}">${title}</h2>${links.map(([url,label])=>`<a href="${url}">${label}</a>`).join('')}</nav>`).join('')}<div class="footer-bottom"><span>© ${new Date().getUTCFullYear()} DryKraft. All rights reserved.</span><div><a href="${escape(app)}/login">Sign in</a><a href="#main">Back to top ${arrow}</a></div></div></div></footer>`;
}
export function renderWebsite(page,{appOrigin='',siteOrigin='' }={}) {
  for(const origin of [appOrigin,siteOrigin])if(origin && !['http:','https:'].includes(new URL(origin).protocol))throw new Error('Website links require an HTTP origin.');
  const isDocs=page.path==='/docs'||page.path.startsWith('/docs/');
  const isProject=page.path==='/open-source';
  const body=isProject?renderProjectWebsite():isDocs?renderDocumentation(page):page.path==='/'?home(appOrigin):page.path==='/guides'?guides(appOrigin):page.path.startsWith('/guides/')?articlePage(page):page.path==='/about'?about(appOrigin):extraFeatures[page.path.split('/').at(-1)]?featurePage(page,appOrigin):productPage(page,appOrigin);
  const title=page.seoTitle || page.title;
  return `<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#ffffff"><title>${escape(title)} - DryKraft</title><meta name="description" content="${escape(page.description)}">${siteOrigin?`<link rel="canonical" href="${escape(siteOrigin+page.path)}"><meta property="og:url" content="${escape(siteOrigin+page.path)}">`:''}<meta property="og:title" content="${escape(title)} - DryKraft"><meta property="og:description" content="${escape(page.description)}"><meta property="og:type" content="website"><meta property="og:image" content="${escape(siteOrigin)}/logo.png"><link rel="icon" href="/icon-ui.png"><link rel="preload" href="/fonts/inter-latin.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/website.css">${isProject?'<link rel="stylesheet" href="/project.css">':''}<script src="/website.js" defer></script></head><body><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><a class="site-brand" href="/" aria-label="DryKraft home"><img src="/logo-ui.png" alt="DryKraft" width="156" height="61"></a><button class="menu-toggle" aria-expanded="false" aria-controls="site-navigation" aria-label="Open navigation"><svg width="23" height="23" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg></button>${siteNavigation(page,appOrigin)}</header><main id="main" tabindex="-1">${body}${isDocs||isProject?'':`<section class="closing"><div><h2>Give your team<br>one place to work.</h2><p>Start your 15-day free trial. Set up the workspace around your business.</p></div><a class="button primary" href="${escape(appOrigin)}/signup">Start your free trial ${arrow}</a></section>`}</main>${siteFooter(appOrigin)}</body></html>`;
}
